    def reverse(s):
        """Reverses the case of a string."""
        return s[::-1]

    def is_lower(s):
        """Checks if a character is in lowercase."""
        return s.islower()

    def is_upper(s):
        """Checks if a character is in uppercase."""
        return s.isupper()

    def reverse_string(s):
        """Reverses the case of a string."""
        return s.swapcase()

    def reverse_case(s):
        """Reverses the case of a string."""
        if is_lower(s):
            return reverse(s).swapcase()
        elif is_upper(s):
            return reverse(s).swapcase()
        else:
